    /// `--help` lists exactly the 8 user commands,
    /// each with one plain-language line free of internal jargon.
    #[test]
    fn help_lists_exactly_eight_commands_with_plain_help_text() {
        let mut cmd = Cli::command();
        cmd.build();

        let visible: Vec<&str> = cmd
            .get_subcommands()
            .filter(|s| !s.is_hide_set())
            .map(|s| s.get_name())
            .collect();
        let expected = [
            "add",
            "status",
            "version",
            "pre",
            "snapshot",
            "init",
            "release",
            "completions",
        ];
        assert_eq!(
            visible.len(),
            8,
            "expected exactly 8 visible commands, got: {visible:?}"
        );
        for name in expected {
            assert!(
                visible.contains(&name),
                "missing {name:?} from visible commands: {visible:?}"
            );
        }

        let banned = [
            "durable release intent",
            "forge snapshot",
            "coordinator revision",
            "schema v",
        ];
        for sub in cmd.get_subcommands().filter(|s| !s.is_hide_set()) {
            let about = sub.get_about().map(|a| a.to_string()).unwrap_or_default();
            assert_eq!(
                about.lines().count().max(1),
                1,
                "{}'s help text must be exactly one line: {about:?}",
                sub.get_name()
            );
            assert!(!about.is_empty(), "{} has no help text", sub.get_name());
            let lower = about.to_lowercase();
            for phrase in banned {
                assert!(
                    !lower.contains(phrase),
                    "{}'s help text contains banned jargon {phrase:?}: {about:?}",
                    sub.get_name()
                );
            }
        }
    }

    /// clap's automatic `help` subcommand is disabled (it would otherwise
    /// widen the eight-command `--help` listing's implicit surface), but a
    /// hidden `help` subcommand of our own parses in its place, and
    /// `-h`/`--help` still work on the root command and on subcommands.
    #[test]
    fn help_subcommand_parses_and_flag_help_still_works() {
        use clap::Parser;

        let help_sub = Cli::try_parse_from(["callisto", "help"]).expect("`callisto help` must parse");
        assert!(matches!(help_sub.command, Command::Help(HelpArgs { command }) if command.is_empty()));

        let help_sub_command =
            Cli::try_parse_from(["callisto", "help", "status"]).expect("`callisto help status` must parse");
        assert!(matches!(help_sub_command.command, Command::Help(HelpArgs { command }) if command == ["status"]));

        let root_flag = Cli::try_parse_from(["callisto", "--help"]);
        assert_eq!(
            root_flag.err().unwrap().kind(),
            clap::error::ErrorKind::DisplayHelp,
            "-h/--help must still work on the root command"
        );

        let sub_flag = Cli::try_parse_from(["callisto", "status", "--help"]);
        assert_eq!(
            sub_flag.err().unwrap().kind(),
            clap::error::ErrorKind::DisplayHelp,
            "-h/--help must still work on subcommands"
        );
    }

    /// Plumbing subcommands stay callable but hidden
    /// from `callisto --help` and `callisto release --help`.
    #[test]
    fn plumbing_subcommands_are_hidden_but_callable() {
        let mut cmd = Cli::command();
        cmd.build();

        for name in ["matrix", "schema", "compose-pr-body", "release-pr", "help"] {
            let sub = cmd
                .get_subcommands()
                .find(|s| s.get_name() == name)
                .unwrap_or_else(|| panic!("{name} must still be a registered subcommand"));
            assert!(sub.is_hide_set(), "{name} must be hidden from top-level --help");
        }

        let release = cmd
            .get_subcommands()
            .find(|s| s.get_name() == "release")
            .expect("release subcommand must exist");
        for name in ["plan", "inspect", "build-python", "artifact-manifest", "execute"] {
            let sub = release
                .get_subcommands()
                .find(|s| s.get_name() == name)
                .unwrap_or_else(|| panic!("release {name} must still be a registered subcommand"));
            assert!(sub.is_hide_set(), "release {name} must be hidden from `release --help`");
        }

        // Still callable: parsing succeeds for every hidden subcommand.
        use clap::Parser;
        assert!(Cli::try_parse_from(["callisto", "matrix"]).is_ok());
        assert!(Cli::try_parse_from(["callisto", "schema"]).is_ok());
        assert!(Cli::try_parse_from(["callisto", "compose-pr-body"]).is_ok());
        assert!(Cli::try_parse_from(["callisto", "help"]).is_ok());
        assert!(Cli::try_parse_from([
            "callisto",
            "release",
            "plan",
            "--package",
            "cargo/demo",
            "--out",
            "intent.json"
        ])
        .is_ok());
        assert!(Cli::try_parse_from(["callisto", "release", "inspect", "--input", "x"]).is_ok());
        assert!(Cli::try_parse_from([
            "callisto",
            "release-pr",
            "decide",
            "--snapshot",
            "-",
            "--repository",
            "o/r",
            "--base-branch",
            "main",
            "--release-branch",
            "release"
        ])
        .is_ok());
    }

    /// `validate` is removed, not merely hidden --
    /// parsing it must fail as an unrecognized subcommand.
    #[test]
    fn validate_subcommand_fails_to_parse() {
        use clap::Parser;
        assert!(
            Cli::try_parse_from(["callisto", "validate"]).is_err(),
            "`validate` must no longer parse as a subcommand"
        );
    }

    /// A comma-separated `--artifact-target` value keeps every
    /// entry, including empties, so `collect_answers` can error naming the empty one.
    #[test]
    fn artifact_target_flag_splits_on_comma() {
        use clap::Parser;
        let cli = Cli::parse_from(["callisto", "init", "--artifact-target", "a,,b"]);
        let Command::Init(args) = cli.command else {
            panic!("expected Init command");
        };
        assert_eq!(args.artifact_targets, vec!["a", "", "b"]);
    }

    /// `schema --type` is a `ValueEnum`: an unrecognized value is a clap usage
    /// error (exit 2); there is no `CliError` variant for this case.
    #[test]
    fn schema_type_rejects_unknown_value_as_a_usage_error() {
        use clap::Parser;
        let err = match Cli::try_parse_from(["callisto", "schema", "--type", "validate"]) {
            Ok(_) => panic!("expected `--type validate` to be rejected"),
            Err(err) => err,
        };
        assert_eq!(err.kind(), clap::error::ErrorKind::InvalidValue);
    }

    /// The on-disk `.changeset/pre.json` file schema is named `pre-state`,
    /// distinct from `callisto pre`'s own `--format json` report -- the
    /// rename this replaces `--type pre` with, since it described the file,
    /// not the command's report.
    #[test]
    fn schema_type_accepts_pre_state() {
        use clap::Parser;
        let cli = Cli::parse_from(["callisto", "schema", "--type", "pre-state"]);
        let Command::Schema(args) = cli.command else {
            panic!("expected Schema command");
        };
        assert_eq!(args.target_type, Some(SchemaReportType::PreState));
    }
}

