    pub id: PackageId,
    /// Absolute path to the package's directory (used for manifest reads).
    pub dir_abs: PathBuf,
    /// Workspace-root-relative path string, stored verbatim on each
    /// PlatformTarget.package_dir.
    pub dir_rel: String,
    pub name: String,
