/// Reads engines.node (npm) and requires-python (python) from
/// `package_dir_abs`'s already-parsed manifest values, in that order, so
/// callers preserve the npm-before-python ordering without
/// a separate sort step. `pkg_json_val`/`pyproject_val` are shared with
/// `assemble_platform_target_group` (see `select_platform_target_source`'s
/// doc comment) so `build_matrix_report` parses each file at most once per
/// package.
pub(crate) fn assemble_runtime_versions(
    package_dir_abs: &Path,
    pkg_json_val: Option<&serde_json::Value>,
    pyproject_val: Option<&toml::Value>,
) -> Result<Vec<RuntimeVersionEntry>, GraphError> {
    let mut entries = Vec::new();

    let pkg_json = package_dir_abs.join("package.json");
    if let Some(val) = pkg_json_val
        && let Some(range) = read_engines_node(&pkg_json, val)?
    {
        entries.push(RuntimeVersionEntry {
            ecosystem: RuntimeEcosystem::Npm,
            field: "engines.node".to_string(),
            range,
        });
    }

    let pyproject = package_dir_abs.join("pyproject.toml");
    if let Some(val) = pyproject_val
        && let Some(range) = read_requires_python(&pyproject, val)?
    {
        entries.push(RuntimeVersionEntry {
            ecosystem: RuntimeEcosystem::Python,
            field: "requires-python".to_string(),
            range,
        });
    }

    Ok(entries)
}

/// Assembles the full MatrixReport for `packages`. Map keys are each
/// package's ecosystem-qualified id (`PackageId::display_name()` -- a bare
/// name when the package was never promoted, `ecosystem/name` once a
/// same-name package in another ecosystem forced promotion; the
/// BTreeMap ordering comes from this for free) so a Cargo package and an npm
/// package sharing a bare name (the common napi split layout) never collide
/// on the same map entry; a package contributes no platformTargets entry when it declares neither
/// napi.targets nor [tool.maturin].targets, and no runtimeVersions entry when
/// it declares neither engines.node nor requires-python.
///
/// Each package's `package.json`/`pyproject.toml` is read and parsed at most
/// once here and the resulting value shared between the platform-target and
/// runtime-version extraction paths, instead of each independently
/// re-reading and re-parsing the same file from disk.
pub(crate) fn build_matrix_report(
    packages: &[MatrixPackageInput],
    napi_crates: Option<&[NapiCrate]>,
) -> Result<MatrixReport, GraphError> {
    let mut platform_targets = BTreeMap::new();
    let mut runtime_versions = BTreeMap::new();
    let mut diagnostics = Vec::new();

    for pkg in packages {
        let pkg_json_val = parse_package_json(&pkg.dir_abs.join("package.json"))?;
        let pyproject_val = parse_pyproject_toml(&pkg.dir_abs.join("pyproject.toml"))?;

        let (group, diags) = assemble_platform_target_group(
            &pkg.dir_abs,
            &pkg.dir_rel,
            &pkg.name,
            &pkg.id,
            pkg_json_val.as_ref(),
            pyproject_val.as_ref(),
        )?;
        if let Some(mut group) = group {
            if let (PlatformTargetKind::Napi, Some(pkg_json), Some(napi_crates), false) =
                (group.kind, pkg_json_val.as_ref(), napi_crates, group.targets.is_empty())
            {
                let manifest_path = napi_manifest_path(pkg, pkg_json, napi_crates)?;
                for target in &mut group.targets {
                    target.manifest_path = manifest_path.clone();
                }
            }
            platform_targets.insert(pkg.id.display_name(), group);
        }
        diagnostics.extend(diags);

        let rv = assemble_runtime_versions(&pkg.dir_abs, pkg_json_val.as_ref(), pyproject_val.as_ref())?;
        if !rv.is_empty() {
            runtime_versions.insert(pkg.id.display_name(), rv);
        }
    }

    Ok(MatrixReport {
        schema_version: callisto_model::PACKAGE_REPORT_SCHEMA_VERSION,
        platform_targets,
        runtime_versions,
        diagnostics,
    })
}

/// One configured `[[release.artifact]]` cargo binary, resolved to its package.
pub(crate) struct ReleaseArtifactInput {
    pub id: PackageId,
    pub name: String,
    /// Workspace-root-relative package directory.
    pub dir_rel: String,
    pub target: String,
    pub asset_name: String,
}

/// Adds one `cargo` group per package from its `[[release.artifact]]` entries;
/// each target's `artifactName` is the slot's configured asset name.
pub(crate) fn add_release_artifact_groups(
    report: &mut MatrixReport,
    artifacts: &[ReleaseArtifactInput],
) -> Result<(), GraphError> {
    const SOURCE: &str = "[[release.artifact]]";
    for artifact in artifacts {
        let group = report
            .platform_targets
            .entry(artifact.id.display_name())
            .or_insert_with(|| PlatformTargetGroup {
                kind: PlatformTargetKind::Cargo,
                source: SOURCE.to_owned(),
                targets: Vec::new(),
            });
        if group.kind != PlatformTargetKind::Cargo {
            return Err(GraphError::PlatformTargetsWithReleaseArtifacts {
                package: artifact.id.clone(),
                source_field: group.source.clone(),
            });
        }
        match build_platform_target(&artifact.target, &artifact.dir_rel, &artifact.name) {
            Some(mut target) => {
                target.artifact_name = artifact.asset_name.clone();
                group.targets.push(target);
            }
            None => report.diagnostics.push(Diagnostic {
                code: DiagnosticCode::UnrecognisedPlatformTriple,
                severity: DiagnosticSeverity::Warning,
                message: format!(
                    "package `{}` declares unrecognised platform triple `{}` in `{SOURCE}`",
                    artifact.name, artifact.target
                ),
                package: Some(artifact.id.clone()),
                path: None,
                escalated_by: None,
                governed_by: None,
            }),
        }
        group.targets.sort_by(|a, b| {
            a.triple
                .cmp(&b.triple)
                .then_with(|| a.artifact_name.cmp(&b.artifact_name))
        });
    }
    report
        .platform_targets
        .retain(|_, group| !group.targets.is_empty() || group.kind != PlatformTargetKind::Cargo);
    Ok(())
}

