        group.targets.sort_by(|a, b| {
            a.triple
                .cmp(&b.triple)
                .then_with(|| a.artifact_name.cmp(&b.artifact_name))
        });
    }
    report
        .platform_targets
        .retain(|_, group| !group.targets.is_empty() || group.kind != PlatformTargetKind::Cargo);
    Ok(())
