122	            candidates: self.binary_packages().map(|package| package.id.clone()).collect(),
123	        };
124	        let found: Vec<&InitPackage> = match self.packages.iter().find(|package| package.id == name) {
125	            Some(package) => vec![package],
126	            None => self.packages.iter().filter(|package| package.name() == name).collect(),
127	        };
128	        match found.as_slice() {
129	            [package] if package.is_binary() && package.supports_artifact_builder() => Ok(package),
130	            [package] if package.is_binary() => Err(GraphError::InitUnsupportedArtifactBuilder {
