169	fn ensure_uninitialized(root: &Path) -> Result<(), GraphError> {
170	    let path = root.join("callisto.toml");
171	    if callisto_model::strict_fs::exists(&path).map_err(io_err(&path))? {
172	        return Err(GraphError::InitAlreadyInitialized { path });
173	    }
174	    Ok(())
175	}
176	
177	fn qualified_id(package: &callisto_model::Package) -> String {
178	    match package.canonical_manifests().next() {
179	        Some(manifest) => format!("{}/{}", manifest.ecosystem().prefix(), package.id.name()),
180	        None => package.id.display_name(),
181	    }
182	}
183	
184	/// Detects the workspace facts `init` reports and builds on.
185	///
186	/// # Errors
187	///
188	/// An existing `callisto.toml`, no Git repository, no usable `origin`, or an
189	/// ambiguous tag convention.
190	pub fn detect<L: ProjectLocator, R: CommandRunner>(
191	    root: &Path,
192	    locator: &L,
193	    runner: &R,
194	) -> Result<InitFacts, GraphError> {
195	    let root = canonical_root(root)?;
196	    ensure_uninitialized(&root)?;
197	    let git_dir = runner.run_with_timeout(programs::GIT, &["rev-parse", "--git-dir"], &root, timeouts::LOCAL_GIT)?;
198	    if git_dir.exit_code != Some(0) {
199	        return Err(GraphError::InitNotGitRepository { root });
200	    }
201	    let origin = optional_git_remote(&root, runner)?;
202	    let head = runner.run_with_timeout(
203	        programs::GIT,
204	        &["rev-parse", "--verify", "--quiet", "HEAD"],
205	        &root,
206	        timeouts::LOCAL_GIT,
207	    )?;
208	
209	    let discovered = Workspace::load(root.clone(), locator, runner)?;
210	    let tag_templates = detect_tag_templates(&discovered)?;
211	    let templates_only = InitFacts {
212	        root: root.clone(),
213	        ecosystems: BTreeSet::new(),
214	        packages: Vec::new(),
215	        origin: origin.as_ref().map(|remote| remote.endpoint.clone()),
216	        origin_repository: origin.as_ref().and_then(|remote| remote.github_repository.clone()),
217	        tag_templates,
218	        has_commit: head.exit_code == Some(0),
219	        has_platform_packages: false,
220	        has_napi_targets: false,
221	        has_maturin_targets: false,
222	    };
223	    let config = resolve_config_text(
224	        &root,
225	        &render_config(
226	            &templates_only,
227	            &InitAnswers {
228	                versioning: Versioning::Independent,
229	                binaries: None,
230	            },
231	        ),
232	    )?;
233	    let workspace = Workspace::load_with_config(root.clone(), config, locator, runner)?;
234	    let tags = workspace.tags()?;
235	    let versions = workspace.base_versions()?;
236	    let ctx = callisto_manifests::OpenContext::for_workspace_root(&workspace.root)?;
237	
238	    let mut packages = Vec::new();
239	    for package in workspace.graph.packages() {
240	        let mut bin_names = Vec::new();
241	        let mut cargo_bin_names = Vec::new();
242	        let mut unsupported_bin_ecosystems = BTreeSet::new();
243	        for decl in package.canonical_manifests() {
244	            let manifest = crate::manifest_cache::open_cached(&workspace.manifest_cache, decl, &ctx)?;
245	            let names = manifest.bin_names()?;
246	            if manifest.ecosystem() == Ecosystem::Cargo {
247	                cargo_bin_names.extend(names.iter().cloned());
248	            } else if !names.is_empty() {
249	                unsupported_bin_ecosystems.insert(manifest.ecosystem().prefix().to_owned());
250	            }
251	            bin_names.extend(names);
252	        }
253	        packages.push(InitPackage {
254	            id: qualified_id(package),
255	            version: versions[&package.id].clone(),
256	            bin_names,
257	            cargo_bin_names,
258	            unsupported_bin_ecosystems: unsupported_bin_ecosystems.into_iter().collect(),
259	            last_tag: tags.last_tag(&package.id).map(|tag| tag.name.clone()),
260	            publish_to: package
261	                .publish_to
262	                .iter()
263	                .map(|target| target.config_str().to_owned())
264	                .filter(|target| target != PublishTarget::None.config_str())
265	                .collect(),
266	            platform: is_platform_package(package),
267	        });
268	    }
269	    packages.sort_by(|a, b| a.id.cmp(&b.id));
270	    let ecosystems = workspace
271	        .graph
272	        .packages()
273	        .flat_map(|package| package.canonical_manifests())
274	        .map(|manifest| manifest.ecosystem())
275	        .collect();
276	    // Counts attached platform packages too: they never get their own `packages` entry,
277	    // so scanning canonical manifests alone finds only co-located ones.
278	    let has_platform_packages = workspace
279	        .graph
280	        .packages()
281	        .any(|package| is_platform_package(package) || workspace.identity.platforms_of(&package.id).next().is_some());
282	
283	    let matrix = crate::commands::matrix::matrix(&workspace, &crate::commands::matrix::MatrixOptions::default())?;
284	    let has_kind = |kind| matrix.platform_targets.values().any(|group| group.kind == kind);
285	
286	    Ok(InitFacts {
287	        ecosystems,
288	        packages,
289	        has_platform_packages,
290	        has_napi_targets: has_kind(callisto_model::PlatformTargetKind::Napi),
291	        has_maturin_targets: has_kind(callisto_model::PlatformTargetKind::Maturin),
292	        ..templates_only
293	    })
294	}
295	
296	/// One tag convention a package's existing tags follow.
297	struct TagMatch {
298	    convention: &'static str,
299	    template: String,
300	    tags: Vec<String>,
301	}
302	
303	/// Matches each package's tags against the candidate conventions; returns the non-default ones to write.
304	fn detect_tag_templates<R: CommandRunner, D: DependencyResolver>(
305	    workspace: &Workspace<'_, R, D>,
306	) -> Result<BTreeMap<String, String>, GraphError> {
307	    let all_tags = crate::tags::fetch_all_tags(workspace.git_access())?;
308	    let mut matches: BTreeMap<String, Vec<TagMatch>> = BTreeMap::new();
309	    for package in workspace
310	        .graph
311	        .packages()
312	        .filter(|package| !is_platform_package(package))
313	    {
314	        let grammar = package.version_grammar()?;
315	        for convention in TAG_CONVENTIONS {
316	            let rendered = if convention == DEFAULT_TAG_CONVENTION {
317	                TagTemplate::default_for(&package.id).as_str()
318	            } else {
319	                convention.replace("{name}", package.id.name())
320	            };
321	            let Ok(template) = TagTemplate::parse(&rendered) else {
322	                continue;
323	            };
324	            // A leading digit keeps `{name}-{version}` from claiming `{name}-v1.0.0` under PEP 440.
325	            let tags: Vec<String> = all_tags
326	                .iter()
327	                .filter(|tag| {
328	                    template.extract_version_str(tag).is_some_and(|version| {
329	                        version.starts_with(|c: char| c.is_ascii_digit()) && Version::parse(version, grammar).is_ok()
330	                    })
331	                })
332	                .cloned()
333	                .collect();
334	            if !tags.is_empty() {
335	                matches.entry(qualified_id(package)).or_default().push(TagMatch {
336	                    convention,
337	                    template: rendered,
338	                    tags,
339	                });
340	            }
341	        }
342	    }
343	
344	    let shared: Vec<String> = matches
345	        .iter()
346	        .filter(|(_, found)| found.iter().any(|found| found.convention == SHARED_TAG_CONVENTION))
347	        .map(|(package, _)| package.clone())
348	        .collect();
349	    if shared.len() > 1 {
350	        return Err(GraphError::InitSharedVersionTag { packages: shared });
351	    }
352	
353	    let mut templates = BTreeMap::new();
354	    for (package, found) in matches {
355	        match found.as_slice() {
356	            [only] => {
357	                if only.convention != DEFAULT_TAG_CONVENTION {
358	                    templates.insert(package, only.template.clone());
359	                }
360	            }
361	            _ => {
362	                return Err(GraphError::InitTagTemplateAmbiguous {
363	                    package,
364	                    matches: found
365	                        .iter()
366	                        .map(|found| format!("`{}` ({})", found.template, found.tags.join(", ")))
367	                        .collect(),
368	                })
369	            }
370	        }
371	    }
372	    Ok(templates)
373	}
374	
375	/// Renders `callisto.toml` from the answers: only answered intent and tag continuity, never defaults.
376	pub fn render_config(facts: &InitFacts, answers: &InitAnswers) -> String {
377	    use toml_edit::{value, Array, ArrayOfTables, DocumentMut, Item, Table};
378	
379	    let mut doc = DocumentMut::new();
380	    if answers.versioning == Versioning::Fixed {
381	        let members: Array = facts
382	            .packages
383	            .iter()
384	            .filter(|package| !package.platform)
385	            .map(|package| package.id.as_str())
386	            .collect();
387	        if !members.is_empty() {
388	            let mut group = Table::new();
389	            group["name"] = value("all");
390	            group["members"] = value(members);
391	            let mut groups = ArrayOfTables::new();
392	            groups.push(group);
393	            doc["fixed-group"] = Item::ArrayOfTables(groups);
394	        }
395	    }
396	    let mut rules: BTreeMap<&str, Table> = BTreeMap::new();
397	    for (package, template) in &facts.tag_templates {
398	        rules.entry(package).or_default()["tag-template"] = value(template.as_str());
399	    }
400	    let product = answers
401	        .binaries
402	        .as_ref()
403	        .and_then(|release| facts.packages.iter().find(|package| package.id == release.product));
404	    if let Some(product) = product {
405	        // Artifact slots derive only for a product that publishes to github-release.
406	        let publish_to: Array = product
407	            .publish_to
408	            .iter()
409	            .map(String::as_str)
410	            .chain([PublishTarget::GitHubRelease.config_str()])
411	            .collect();
412	        rules.entry(&product.id).or_default()["publish-to"] = value(publish_to);
413	    }
414	    if !rules.is_empty() {
415	        let mut tables = ArrayOfTables::new();
416	        for (package, rule) in rules {
417	            let mut table = Table::new();
418	            table["match"] = value(package);
419	            table.extend(rule);
420	            tables.push(table);
421	        }
422	        doc["package"] = Item::ArrayOfTables(tables);
423	    }
424	    if let Some(release) = &answers.binaries {
425	        let bin_names = product
426	            .map(|package| package.cargo_bin_names.as_slice())
427	            .unwrap_or_default();
428	        let mut table = Table::new();
429	        table["product-package"] = value(release.product.as_str());
430	        table["forge-repository"] = value(release.forge_repository.as_slug());
431	        let mut artifacts = ArrayOfTables::new();
432	        for target in &release.targets {
433	            for bin in bin_names {
434	                let extension = if target.contains("windows") { "zip" } else { "tar.gz" };
435	                let mut artifact = Table::new();
436	                artifact["package"] = value(release.product.as_str());
437	                artifact["target"] = value(target.as_str());
438	                artifact["asset-name"] = value(format!("{bin}-{target}.{extension}"));
439	                artifacts.push(artifact);
440	            }
441	        }
442	        table["artifact"] = Item::ArrayOfTables(artifacts);
443	        doc["release"] = Item::Table(table);
444	    }
445	    let body = doc.to_string();
446	    if body.is_empty() {
447	        CONFIG_HEADER.to_owned()
448	    } else {
449	        format!("{CONFIG_HEADER}\n{body}")
450	    }
451	}
452	
453	fn resolve_config_text(root: &Path, text: &str) -> Result<ResolvedConfig, GraphError> {
454	    let raw = toml::from_str::<RawConfig>(text).map_err(|error| ConfigError::ParseToml {
455	        path: root.join("callisto.toml"),
456	        message: error.to_string(),
457	    })?;
458	    Ok(crate::config::resolve(root, raw)?)
459	}
460	
461	/// The first release `config` would produce, from the plan behind `release --dry-run`.
462	///
463	/// # Errors
464	///
465	/// `config` fails to resolve, or the release plan cannot be derived.
466	pub fn preview<L: ProjectLocator, R: CommandRunner>(
467	    facts: &InitFacts,
468	    config: &str,
469	    locator: &L,
470	    runner: &R,
471	) -> Result<Option<LocalReleasePlan>, GraphError> {
472	    let resolved = resolve_config_text(&facts.root, config)?;
473	    let workspace = Workspace::load_with_config(facts.root.clone(), resolved, locator, runner)?;
474	    plan_workspace_release(&workspace, &[], LocalReleaseSource::Preview)
475	}
476	
477	/// Parses a forge repository answer, which the release plan requires to be `origin`'s GitHub repository.
478	///
479	/// # Errors
480	///
481	/// `value` is not a GitHub `owner/repo`, or is not `origin`'s.
482	pub fn forge_repository(facts: &InitFacts, value: &str) -> Result<GitHubRepository, GraphError> {
483	    let repository = GitHubRepository::parse(value.trim()).map_err(|error| GraphError::InitInvalidForgeRepository {
484	        value: value.to_owned(),
485	        reason: error.to_string(),
486	    })?;
487	    if facts.origin_repository.as_ref() != Some(&repository) {
488	        return Err(GraphError::InitForgeRepositoryMismatch {
489	            configured: repository.as_slug(),
490	            origin: facts.origin.clone().unwrap_or_else(|| "none".to_owned()),
491	        });
492	    }
493	    Ok(repository)
494	}
495	
496	/// Validates artifact target triples.
497	///
498	/// # Errors
499	///
500	/// An empty or repeated triple.
501	pub fn validate_targets(targets: &[String]) -> Result<Vec<String>, GraphError> {
502	    let mut seen = BTreeSet::new();
503	    for target in targets {
504	        let invalid = |reason| GraphError::InitInvalidTargetTriple {
505	            triple: target.clone(),
506	            reason,
507	        };
508	        if target.trim().is_empty() {
509	            return Err(invalid("it is empty"));
510	        }
511	        if !seen.insert(target.as_str()) {
512	            return Err(invalid("it is given more than once"));
513	        }
514	    }
515	    Ok(targets.to_vec())
516	}
517	
518	/// Files `init` writes, or would write under `--dry-run`: `callisto.toml`, `.changeset/README.md`
519	/// unless it already exists, and the release workflow when `workflow` is `true`. Reads current
520	/// disk state, so callers compute this before writing anything.
521	///
522	/// # Errors
523	///
524	/// The README's existence cannot be determined.
525	pub fn init_files(root: &Path, workflow: bool) -> Result<Vec<PathBuf>, GraphError> {
526	    let readme = root.join(".changeset/README.md");
527	    let mut files = vec![root.join("callisto.toml")];
528	    if !callisto_model::strict_fs::exists(&readme).map_err(io_err(&readme))? {
529	        files.push(readme);
530	    }
531	    if workflow {
532	        files.push(workflow_path(root));
533	    }
534	    Ok(files)
535	}
536	
537	/// Writes `callisto.toml` and, when absent, `.changeset/README.md`.
538	///
539	/// # Errors
540	///
541	/// `callisto.toml` already exists, or a write fails.
542	pub fn write(root: &Path, config: &str, permit: &ApplyPermit) -> Result<InitReport, GraphError> {
543	    ensure_uninitialized(root)?;
544	    let config_path = root.join("callisto.toml");
545	    let files = init_files(root, false)?;
546	    callisto_model::atomic::atomic_write(&config_path, config, permit).map_err(io_err(&config_path))?;
547	    write_changeset_readme(root, permit)?;
548	    Ok(InitReport {
549	        schema_version: SCHEMA_VERSION,
550	        initialized: true,
551	        config_path,
552	        config: config.to_owned(),
553	        files,
554	        diagnostics: Vec::new(),
555	    })
556	}
557	
558	/// Creates `.changeset/README.md` unless it already exists.
559	///
560	/// # Errors

file.content:
//! `callisto init`: first-run fact detection, config rendering, preview, and scaffolding.

use std::collections::{BTreeMap, BTreeSet};
use std::path::{Path, PathBuf};

use callisto_model::{
    ApplyPermit, CommandRunner, Diagnostic, DiagnosticCode, DiagnosticSeverity, Ecosystem, GitHubRepository,
    InitReport, PublishTarget, TagName, TagTemplate, Version, SCHEMA_VERSION,
};

use crate::commands::release::{
    canonical_root, is_platform_package, optional_git_remote, plan_workspace_release, programs, timeouts,
    LocalReleasePlan, LocalReleaseSource,
};
use crate::config::raw::RawConfig;
use crate::error::{ConfigError, GraphError};
use crate::{DependencyResolver, ProjectLocator, ResolvedConfig, Workspace};

/// Content of the scaffolded `.changeset/README.md`.
pub const CHANGESET_README: &str = "# Changesets

This directory contains markdown changeset files generated by Callisto CLI (`callisto add`).
Each changeset describes a package version bump and associated release summary.
";

const CONFIG_HEADER: &str = "# callisto configuration\n";
const DEFAULT_TAG_CONVENTION: &str = "{name}@{version}";
const SHARED_TAG_CONVENTION: &str = "v{version}";
const TAG_CONVENTIONS: [&str; 4] = [
    DEFAULT_TAG_CONVENTION,
    "{name}-v{version}",
    "{name}-{version}",
    SHARED_TAG_CONVENTION,
];

/// How packages version relative to each other.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Versioning {
    /// Every package shares one version (`[[fixed-group]] name = "all"`).
    Fixed,
    Independent,
}

/// One discovered workspace package.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct InitPackage {
    /// Ecosystem-qualified id, e.g. `cargo/app`.
    pub id: String,
    pub version: Version,
    /// Executables the package builds; empty for a library.
    pub bin_names: Vec<String>,
    /// Executables provided by Cargo and eligible for Cargo artifact builds.
    pub cargo_bin_names: Vec<String>,
    /// Ecosystems that provide executables but do not yet have an artifact builder.
    pub unsupported_bin_ecosystems: Vec<String>,
    /// Latest release tag under the package's detected convention.
    pub last_tag: Option<TagName>,
    /// Detected `publish-to` targets (`none` omitted).
    pub publish_to: Vec<String>,
    /// A napi/maturin platform package: never grouped or shipped.
    pub platform: bool,
}

impl InitPackage {
    pub fn is_binary(&self) -> bool {
        !self.platform && !self.bin_names.is_empty()
    }

    fn supports_artifact_builder(&self) -> bool {
        self.id.starts_with("cargo/") && !self.cargo_bin_names.is_empty()
    }

    fn name(&self) -> &str {
        self.id.split_once('/').map_or(self.id.as_str(), |(_, name)| name)
    }
}

/// Everything `init` detects before asking a question.
#[derive(Clone, Debug)]
pub struct InitFacts {
    pub root: PathBuf,
    pub ecosystems: BTreeSet<Ecosystem>,
    pub packages: Vec<InitPackage>,
    /// Canonical `origin` push URL, or `None` when no `origin` remote is configured.
    pub origin: Option<String>,
    /// `origin` as a GitHub `owner/repo`, when it is one.
    pub origin_repository: Option<GitHubRepository>,
    /// Non-default tag templates to write, keyed by qualified package id.
    pub tag_templates: BTreeMap<String, String>,
    /// `false` in a repository with no commit yet, where no release can be planned.
    pub has_commit: bool,
    /// A package ships napi/maturin platform builds -- either its own canonical
    /// manifest is platform-tagged, or a platform package is attached to it from
    /// a sibling directory (`IdentityIndex::platforms_of`, e.g. napi's per-arch
    /// packages). Mirrors `commands::release::local::ci_release_route`'s own
    /// platform-package check.
    pub has_platform_packages: bool,
    /// Some package declares `napi.targets` (`callisto matrix`'s napi entries).
    pub has_napi_targets: bool,
    /// Some package declares `[tool.maturin].targets`.
    pub has_maturin_targets: bool,
}

impl InitFacts {
    pub fn binary_packages(&self) -> impl Iterator<Item = &InitPackage> {
        self.packages
            .iter()
            .filter(|package| package.is_binary() && package.supports_artifact_builder())
    }

    pub fn unsupported_artifact_packages(&self) -> impl Iterator<Item = &InitPackage> {
        self.packages
            .iter()
            .filter(|package| !package.supports_artifact_builder() && !package.unsupported_bin_ecosystems.is_empty())
    }

    /// Resolves `name` (qualified or bare) to a binary-producing package.
    pub fn product_package(&self, name: &str) -> Result<&InitPackage, GraphError> {
        let invalid = |reason| GraphError::InitInvalidProductPackage {
            package: name.to_owned(),
            reason,
            candidates: self.binary_packages().map(|package| package.id.clone()).collect(),
        };
        let found: Vec<&InitPackage> = match self.packages.iter().find(|package| package.id == name) {
            Some(package) => vec![package],
            None => self.packages.iter().filter(|package| package.name() == name).collect(),
        };
        match found.as_slice() {
            [package] if package.is_binary() && package.supports_artifact_builder() => Ok(package),
            [package] if package.is_binary() => Err(GraphError::InitUnsupportedArtifactBuilder {
                package: package.id.clone(),
                ecosystem: package.unsupported_bin_ecosystems.first().cloned().unwrap_or_else(|| {
                    package
                        .id
                        .split_once('/')
                        .map_or("unknown", |(ecosystem, _)| ecosystem)
                        .to_owned()
                }),
            }),
            [_] => Err(invalid("it does not produce a binary artifact")),
            _ => Err(invalid("it is not a workspace package")),
        }
    }
}

/// Opt-in to shipping binaries as GitHub release assets.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct BinaryRelease {
    /// Qualified id of the product package.
    pub product: String,
    pub forge_repository: GitHubRepository,
    pub targets: Vec<String>,
}

/// The operator's intent; everything else is detected.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct InitAnswers {
    pub versioning: Versioning,
    pub binaries: Option<BinaryRelease>,
}

fn io_err(path: &Path) -> impl Fn(std::io::Error) -> GraphError + '_ {
    move |error| GraphError::InitIo {
        path: path.to_path_buf(),
        message: error.to_string(),
    }
}

fn ensure_uninitialized(root: &Path) -> Result<(), GraphError> {
    let path = root.join("callisto.toml");
    if callisto_model::strict_fs::exists(&path).map_err(io_err(&path))? {
        return Err(GraphError::InitAlreadyInitialized { path });
    }
    Ok(())
}

fn qualified_id(package: &callisto_model::Package) -> String {
    match package.canonical_manifests().next() {
        Some(manifest) => format!("{}/{}", manifest.ecosystem().prefix(), package.id.name()),
        None => package.id.display_name(),
    }
}

/// Detects the workspace facts `init` reports and builds on.
///
/// # Errors
///
/// An existing `callisto.toml`, no Git repository, no usable `origin`, or an
/// ambiguous tag convention.
pub fn detect<L: ProjectLocator, R: CommandRunner>(
    root: &Path,
    locator: &L,
    runner: &R,
) -> Result<InitFacts, GraphError> {
    let root = canonical_root(root)?;
    ensure_uninitialized(&root)?;
    let git_dir = runner.run_with_timeout(programs::GIT, &["rev-parse", "--git-dir"], &root, timeouts::LOCAL_GIT)?;
    if git_dir.exit_code != Some(0) {
        return Err(GraphError::InitNotGitRepository { root });
    }
    let origin = optional_git_remote(&root, runner)?;
    let head = runner.run_with_timeout(
        programs::GIT,
        &["rev-parse", "--verify", "--quiet", "HEAD"],
        &root,
        timeouts::LOCAL_GIT,
    )?;

    let discovered = Workspace::load(root.clone(), locator, runner)?;
    let tag_templates = detect_tag_templates(&discovered)?;
    let templates_only = InitFacts {
        root: root.clone(),
        ecosystems: BTreeSet::new(),
        packages: Vec::new(),
        origin: origin.as_ref().map(|remote| remote.endpoint.clone()),
        origin_repository: origin.as_ref().and_then(|remote| remote.github_repository.clone()),
        tag_templates,
        has_commit: head.exit_code == Some(0),
        has_platform_packages: false,
        has_napi_targets: false,
        has_maturin_targets: false,
    };
    let config = resolve_config_text(
        &root,
        &render_config(
            &templates_only,
            &InitAnswers {
                versioning: Versioning::Independent,
                binaries: None,
            },
        ),
    )?;
    let workspace = Workspace::load_with_config(root.clone(), config, locator, runner)?;
    let tags = workspace.tags()?;
    let versions = workspace.base_versions()?;
    let ctx = callisto_manifests::OpenContext::for_workspace_root(&workspace.root)?;

    let mut packages = Vec::new();
    for package in workspace.graph.packages() {
        let mut bin_names = Vec::new();
        let mut cargo_bin_names = Vec::new();
        let mut unsupported_bin_ecosystems = BTreeSet::new();
        for decl in package.canonical_manifests() {
            let manifest = crate::manifest_cache::open_cached(&workspace.manifest_cache, decl, &ctx)?;
            let names = manifest.bin_names()?;
            if manifest.ecosystem() == Ecosystem::Cargo {
                cargo_bin_names.extend(names.iter().cloned());
            } else if !names.is_empty() {
                unsupported_bin_ecosystems.insert(manifest.ecosystem().prefix().to_owned());
            }
            bin_names.extend(names);
        }
        packages.push(InitPackage {
            id: qualified_id(package),
            version: versions[&package.id].clone(),
            bin_names,
            cargo_bin_names,
            unsupported_bin_ecosystems: unsupported_bin_ecosystems.into_iter().collect(),
            last_tag: tags.last_tag(&package.id).map(|tag| tag.name.clone()),
            publish_to: package
                .publish_to
                .iter()
                .map(|target| target.config_str().to_owned())
                .filter(|target| target != PublishTarget::None.config_str())
                .collect(),
            platform: is_platform_package(package),
        });
    }
    packages.sort_by(|a, b| a.id.cmp(&b.id));
    let ecosystems = workspace
        .graph
        .packages()
        .flat_map(|package| package.canonical_manifests())
        .map(|manifest| manifest.ecosystem())
        .collect();
    // Counts attached platform packages too: they never get their own `packages` entry,
    // so scanning canonical manifests alone finds only co-located ones.
    let has_platform_packages = workspace
        .graph
        .packages()
        .any(|package| is_platform_package(package) || workspace.identity.platforms_of(&package.id).next().is_some());

    let matrix = crate::commands::matrix::matrix(&workspace, &crate::commands::matrix::MatrixOptions::default())?;
    let has_kind = |kind| matrix.platform_targets.values().any(|group| group.kind == kind);

    Ok(InitFacts {
        ecosystems,
        packages,
        has_platform_packages,
        has_napi_targets: has_kind(callisto_model::PlatformTargetKind::Napi),
        has_maturin_targets: has_kind(callisto_model::PlatformTargetKind::Maturin),
        ..templates_only
    })
}

/// One tag convention a package's existing tags follow.
struct TagMatch {
    convention: &'static str,
    template: String,
    tags: Vec<String>,
}

/// Matches each package's tags against the candidate conventions; returns the non-default ones to write.
fn detect_tag_templates<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
) -> Result<BTreeMap<String, String>, GraphError> {
    let all_tags = crate::tags::fetch_all_tags(workspace.git_access())?;
    let mut matches: BTreeMap<String, Vec<TagMatch>> = BTreeMap::new();
    for package in workspace
        .graph
        .packages()
        .filter(|package| !is_platform_package(package))
    {
        let grammar = package.version_grammar()?;
        for convention in TAG_CONVENTIONS {
            let rendered = if convention == DEFAULT_TAG_CONVENTION {
                TagTemplate::default_for(&package.id).as_str()
            } else {
                convention.replace("{name}", package.id.name())
            };
            let Ok(template) = TagTemplate::parse(&rendered) else {
                continue;
            };
            // A leading digit keeps `{name}-{version}` from claiming `{name}-v1.0.0` under PEP 440.
            let tags: Vec<String> = all_tags
                .iter()
                .filter(|tag| {
                    template.extract_version_str(tag).is_some_and(|version| {
                        version.starts_with(|c: char| c.is_ascii_digit()) && Version::parse(version, grammar).is_ok()
                    })
                })
                .cloned()
                .collect();
            if !tags.is_empty() {
                matches.entry(qualified_id(package)).or_default().push(TagMatch {
                    convention,
                    template: rendered,
                    tags,
                });
            }
        }
    }

    let shared: Vec<String> = matches
        .iter()
        .filter(|(_, found)| found.iter().any(|found| found.convention == SHARED_TAG_CONVENTION))
        .map(|(package, _)| package.clone())
        .collect();
    if shared.len() > 1 {
        return Err(GraphError::InitSharedVersionTag { packages: shared });
    }

    let mut templates = BTreeMap::new();
    for (package, found) in matches {
        match found.as_slice() {
            [only] => {
                if only.convention != DEFAULT_TAG_CONVENTION {
                    templates.insert(package, only.template.clone());
                }
            }
            _ => {
                return Err(GraphError::InitTagTemplateAmbiguous {
                    package,
                    matches: found
                        .iter()
                        .map(|found| format!("`{}` ({})", found.template, found.tags.join(", ")))
                        .collect(),
                })
            }
        }
    }
    Ok(templates)
}

/// Renders `callisto.toml` from the answers: only answered intent and tag continuity, never defaults.
pub fn render_config(facts: &InitFacts, answers: &InitAnswers) -> String {
    use toml_edit::{value, Array, ArrayOfTables, DocumentMut, Item, Table};

    let mut doc = DocumentMut::new();
    if answers.versioning == Versioning::Fixed {
        let members: Array = facts
            .packages
            .iter()
            .filter(|package| !package.platform)
            .map(|package| package.id.as_str())
            .collect();
        if !members.is_empty() {
            let mut group = Table::new();
            group["name"] = value("all");
            group["members"] = value(members);
            let mut groups = ArrayOfTables::new();
            groups.push(group);
            doc["fixed-group"] = Item::ArrayOfTables(groups);
        }
    }
    let mut rules: BTreeMap<&str, Table> = BTreeMap::new();
    for (package, template) in &facts.tag_templates {
        rules.entry(package).or_default()["tag-template"] = value(template.as_str());
    }
    let product = answers
        .binaries
        .as_ref()
        .and_then(|release| facts.packages.iter().find(|package| package.id == release.product));
    if let Some(product) = product {
        // Artifact slots derive only for a product that publishes to github-release.
        let publish_to: Array = product
            .publish_to
            .iter()
            .map(String::as_str)
            .chain([PublishTarget::GitHubRelease.config_str()])
            .collect();
        rules.entry(&product.id).or_default()["publish-to"] = value(publish_to);
    }
    if !rules.is_empty() {
        let mut tables = ArrayOfTables::new();
        for (package, rule) in rules {
            let mut table = Table::new();
            table["match"] = value(package);
            table.extend(rule);
            tables.push(table);
        }
        doc["package"] = Item::ArrayOfTables(tables);
    }
    if let Some(release) = &answers.binaries {
        let bin_names = product
            .map(|package| package.cargo_bin_names.as_slice())
            .unwrap_or_default();
        let mut table = Table::new();
        table["product-package"] = value(release.product.as_str());
        table["forge-repository"] = value(release.forge_repository.as_slug());
        let mut artifacts = ArrayOfTables::new();
        for target in &release.targets {
            for bin in bin_names {
                let extension = if target.contains("windows") { "zip" } else { "tar.gz" };
                let mut artifact = Table::new();
                artifact["package"] = value(release.product.as_str());
                artifact["target"] = value(target.as_str());
                artifact["asset-name"] = value(format!("{bin}-{target}.{extension}"));
                artifacts.push(artifact);
            }
        }
        table["artifact"] = Item::ArrayOfTables(artifacts);
        doc["release"] = Item::Table(table);
    }
    let body = doc.to_string();
    if body.is_empty() {
        CONFIG_HEADER.to_owned()
    } else {
        format!("{CONFIG_HEADER}\n{body}")
    }
}

fn resolve_config_text(root: &Path, text: &str) -> Result<ResolvedConfig, GraphError> {
    let raw = toml::from_str::<RawConfig>(text).map_err(|error| ConfigError::ParseToml {
        path: root.join("callisto.toml"),
        message: error.to_string(),
    })?;
    Ok(crate::config::resolve(root, raw)?)
}

/// The first release `config` would produce, from the plan behind `release --dry-run`.
///
/// # Errors
///
/// `config` fails to resolve, or the release plan cannot be derived.
pub fn preview<L: ProjectLocator, R: CommandRunner>(
    facts: &InitFacts,
    config: &str,
    locator: &L,
    runner: &R,
) -> Result<Option<LocalReleasePlan>, GraphError> {
    let resolved = resolve_config_text(&facts.root, config)?;
    let workspace = Workspace::load_with_config(facts.root.clone(), resolved, locator, runner)?;
    plan_workspace_release(&workspace, &[], LocalReleaseSource::Preview)
}

/// Parses a forge repository answer, which the release plan requires to be `origin`'s GitHub repository.
///
/// # Errors
///
/// `value` is not a GitHub `owner/repo`, or is not `origin`'s.
pub fn forge_repository(facts: &InitFacts, value: &str) -> Result<GitHubRepository, GraphError> {
    let repository = GitHubRepository::parse(value.trim()).map_err(|error| GraphError::InitInvalidForgeRepository {
        value: value.to_owned(),
        reason: error.to_string(),
    })?;
    if facts.origin_repository.as_ref() != Some(&repository) {
        return Err(GraphError::InitForgeRepositoryMismatch {
            configured: repository.as_slug(),
            origin: facts.origin.clone().unwrap_or_else(|| "none".to_owned()),
        });
    }
    Ok(repository)
}

/// Validates artifact target triples.
///
/// # Errors
///
/// An empty or repeated triple.
pub fn validate_targets(targets: &[String]) -> Result<Vec<String>, GraphError> {
    let mut seen = BTreeSet::new();
    for target in targets {
        let invalid = |reason| GraphError::InitInvalidTargetTriple {
            triple: target.clone(),
            reason,
        };
        if target.trim().is_empty() {
            return Err(invalid("it is empty"));
        }
        if !seen.insert(target.as_str()) {
            return Err(invalid("it is given more than once"));
        }
    }
    Ok(targets.to_vec())
}

/// Files `init` writes, or would write under `--dry-run`: `callisto.toml`, `.changeset/README.md`
/// unless it already exists, and the release workflow when `workflow` is `true`. Reads current
/// disk state, so callers compute this before writing anything.
///
/// # Errors
///
/// The README's existence cannot be determined.
pub fn init_files(root: &Path, workflow: bool) -> Result<Vec<PathBuf>, GraphError> {
    let readme = root.join(".changeset/README.md");
    let mut files = vec![root.join("callisto.toml")];
    if !callisto_model::strict_fs::exists(&readme).map_err(io_err(&readme))? {
        files.push(readme);
    }
    if workflow {
        files.push(workflow_path(root));
    }
    Ok(files)
}

/// Writes `callisto.toml` and, when absent, `.changeset/README.md`.
///
/// # Errors
///
/// `callisto.toml` already exists, or a write fails.
pub fn write(root: &Path, config: &str, permit: &ApplyPermit) -> Result<InitReport, GraphError> {
    ensure_uninitialized(root)?;
    let config_path = root.join("callisto.toml");
    let files = init_files(root, false)?;
    callisto_model::atomic::atomic_write(&config_path, config, permit).map_err(io_err(&config_path))?;
    write_changeset_readme(root, permit)?;
    Ok(InitReport {
        schema_version: SCHEMA_VERSION,
        initialized: true,
        config_path,
        config: config.to_owned(),
        files,
        diagnostics: Vec::new(),
    })
}

